hook_script:
"""Experiment D: per-turn reminder + PreToolUse deny until a PIRA module file has been Read. No Skill.

State per session (hash of session_id) under PIRA_ROUTING_STATE_DIR: the set of module files read so
far. Any tool other than a Read of a module file is denied until at least one module has been read
in the session. Dependency expansion cannot be verified here; it is only stated in the reminder.
"""
import hashlib
import json
import os
import sys
from pathlib import Path

MODULE_SUFFIXES = (
    "USER.md", "modules/RESEARCH_POLICY.md", "modules/PAPER_READING.md", "modules/CODING_STYLE.md",
    "modules/SCIENTIFIC_WRITING.md", "modules/PUBLIC_FIGURE_STYLE.md", "modules/EXPLAIN_STYLE.md",
    "modules/GUIDANCE.md", "modules/MAINTENANCE.md",
)
REMINDER = (
    "PIRA routing is pending. Before any other tool call or your answer, Read the exact PIRA module files "
    "the project policy requires for this task, including canonical dependencies (paper_reading, coding, "
    "writing and public_figure require research). Tools other than those module Reads are blocked until "
    "a module has been read. If no module applies, answer directly without tools."
)


def state_path(session_id: str) -> Path:
    root = Path(os.environ.get("PIRA_ROUTING_STATE_DIR") or Path(os.environ.get("TEMP", "/tmp")) / "pira-lite")
    return root / hashlib.sha256(session_id.encode("utf-8")).hexdigest() / "lite.json"


def load(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {"loaded": []}


def save(path: Path, state: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(state), encoding="utf-8")


def module_of(tool_input: dict) -> str | None:
    file_path = str(tool_input.get("file_path", "")).replace("\\", "/")
    return next((suffix for suffix in MODULE_SUFFIXES if file_path.endswith(suffix)), None)


def main() -> int:
    data = json.load(sys.stdin)
    event = data.get("hook_event_name", "")
    session_id = str(data.get("session_id", "")) or "unknown"
    path = state_path(session_id)
    state = load(path)
    if event in ("SessionStart", "UserPromptSubmit"):
        if event == "SessionStart":
            save(path, {"loaded": []})
        print(json.dumps({"hookSpecificOutput": {"hookEventName": event, "additionalContext": REMINDER}}))
        return 0
    tool_name = str(data.get("tool_name", ""))
    tool_input = data.get("tool_input") if isinstance(data.get("tool_input"), dict) else {}
    if event == "PreToolUse":
        if tool_name == "Read" and module_of(tool_input):
            return 0
        if state["loaded"]:
            return 0
        print(json.dumps({"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny",
                                                 "permissionDecisionReason": REMINDER}}))
        return 0
    if event == "PostToolUse" and tool_name == "Read":
        module = module_of(tool_input)
        if module and module not in state["loaded"]:
            state["loaded"].append(module)
            save(path, state)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
